import sys

def find_arithmetic_sequence(N, a):
    if N == 4:
        d1 = a[1] - a[0]
        d2 = a[2] - a[1]
        d3 = a[3] - a[2]
        if d1 == d2 == d3:
            return a
        elif d1 == d2:
            return [a[0], a[1], a[2], a[1] + d1]
        elif d1 == d3:
            return [a[0], a[1], a[0] + d1, a[3]]
        else:
            return [a[0], a[0] + d2, a[0] + 2 * d2, a[0] + 3 * d2]
    else:
        d1 = a[1] - a[0]
        for i in range(2, N - 1):
            d2 = a[i+1] - a[i]
            if d1 != d2:
                if i == 2:
                    d1 = d2
                else:
                    d1 = a[i] - a[i-1]
                break
        b = [a[0]]
        for i in range(1, N):
            b.append(b[-1] + d1)
        return b

input = sys.stdin.read().strip().split()
index = 0
T = int(input[index])
index += 1
results = []
for _ in range(T):
    N = int(input[index])
    index += 1
    a = list(map(int, input[index:index+N]))
    index += N
    results.extend(find_arithmetic_sequence(N, a))
print(' '.join(map(str, results)))
